const client = $input.first().json;
const timezone = client.timezone || 'UTC';
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {timeZone: timezone, year:'numeric', month:'2-digit', day:'2-digit'}).formatToParts(new Date()).map(({type,value}) => [type,value]));
const localToday = new Date(Date.UTC(Number(parts.year), Number(parts.month)-1, Number(parts.day)));
const iso = (date) => date.toISOString().slice(0,10);
const shift = (date, days) => { const copy = new Date(date); copy.setUTCDate(copy.getUTCDate()+days); return copy; };
const currentEnd = shift(localToday,-1);
const currentStart = shift(currentEnd,-29);
const previousEnd = shift(currentStart,-1);
const previousStart = shift(previousEnd,-29);
return [{json:{...client, kpis:Array.isArray(client.kpis)?client.kpis:String(client.kpis||'').split(',').map(k=>k.trim()).filter(Boolean), period:{current:{start:iso(currentStart),end:iso(currentEnd)},previous:{start:iso(previousStart),end:iso(previousEnd)}}}}];

'use strict';

const METRIC_NAMES = Object.freeze({
  sessions: 'sessions',
  totalUsers: 'users',
  newUsers: 'new_users',
  conversions: 'conversions',
});

function isoDate(value) {
  const text = String(value ?? '');
  if (!/^\d{8}$/.test(text)) throw new TypeError(`Invalid GA4 date '${text}'; expected YYYYMMDD.`);
  const iso = `${text.slice(0, 4)}-${text.slice(4, 6)}-${text.slice(6, 8)}`;
  if (Number.isNaN(Date.parse(`${iso}T00:00:00Z`))) throw new TypeError(`Invalid GA4 date '${text}'.`);
  return iso;
}

function numberValue(value, metric, rowIndex) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) {
    throw new TypeError(`GA4 row ${rowIndex + 1} has a non-numeric ${metric} value.`);
  }
  return parsed;
}

function mapGa4RunReport(response) {
  if (!response || typeof response !== 'object' || Array.isArray(response)) {
    throw new TypeError('GA4 runReport response must be an object.');
  }
  const dimensionHeaders = (response.dimensionHeaders ?? []).map((header) => header.name);
  const dateIndex = dimensionHeaders.indexOf('date');
  if (dateIndex < 0) throw new TypeError("GA4 response is missing the 'date' dimension.");

  const metricHeaders = (response.metricHeaders ?? []).map((header) => header.name);
  for (const required of Object.keys(METRIC_NAMES)) {
    if (!metricHeaders.includes(required)) throw new TypeError(`GA4 response is missing metric '${required}'.`);
  }

  const rows = (response.rows ?? []).map((row, rowIndex) => {
    const mapped = { date: isoDate(row.dimensionValues?.[dateIndex]?.value) };
    metricHeaders.forEach((metric, metricIndex) => {
      const target = METRIC_NAMES[metric];
      if (target) mapped[target] = numberValue(row.metricValues?.[metricIndex]?.value, metric, rowIndex);
    });
    return mapped;
  });
  rows.sort((left, right) => left.date.localeCompare(right.date));
  return { rows };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { mapGa4RunReport };
if (typeof $input !== 'undefined') {
  const client = $('Prepare Client and Periods').first().json;
  return [{ json: { ...client, ga4: mapGa4RunReport($input.first().json), meta: null, gads: null, extra: null } }];
}

'use strict';

/** Pure KPI calculator plus a raw-paste n8n Code-node entrypoint. */
const DEFINITIONS = Object.freeze({
  sessions:['Sessions','count','ga4'], users:['Users','count','ga4'], new_users:['New users','count','ga4'], conversions:['Conversions','count','ga4'],
  spend:['Ad spend','currency','ads'], impressions:['Impressions','count','ads'], clicks:['Clicks','count','ads'], ctr:['Click-through rate','ratio','ads'],
  cpc:['Cost per click','currency','ads'], leads:['Leads','count','ads'], cpl:['Cost per lead','currency','ads'], purchases:['Purchases','count','ads'],
  revenue:['Revenue','currency','ads'], roas:['Return on ad spend','ratio','ads'],
});
const GA4_KEYS=['sessions','users','new_users','conversions'];
const ADS_KEYS=['spend','impressions','clicks','leads','purchases','revenue'];
const empty=(keys,value=0)=>Object.fromEntries(keys.map(k=>[k,value]));
const number=value=>{ const n=Number(value); return value===null||value===''||!Number.isFinite(n)?0:n; };
const validDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(`${value}T00:00:00Z`));

function sumRows(rows,keys,period,quality,source){
  const out=empty(keys);
  for(const row of rows){
    if(!validDate(row.date)){ quality.push({code:'invalid_date',source,detail:'A row was skipped because date must be YYYY-MM-DD.'}); continue; }
    if(row.date<period.start||row.date>period.end) continue;
    for(const key of keys) out[key]+=number(row[key]);
  }
  return out;
}
function ratio(n,d,key,period,quality){
  if(d===0){ quality.push({code:'zero_divisor',kpi:key,period,detail:`${key} is null because its denominator is zero.`}); return null; }
  return n/d;
}
function derived(t,period,q){return {...t,ctr:ratio(t.clicks,t.impressions,'ctr',period,q),cpc:ratio(t.spend,t.clicks,'cpc',period,q),cpl:ratio(t.spend,t.leads,'cpl',period,q),roas:ratio(t.revenue,t.spend,'roas',period,q)};}
function monthLabel(iso){const [y,m]=iso.split('-').map(Number);return new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(y,m-1,1)));}

function buildKpiReport(input){
  if(!input?.period?.current||!input?.period?.previous) throw new TypeError('period.current and period.previous are required');
  for(const [name,period] of Object.entries(input.period)) if(!validDate(period.start)||!validDate(period.end)||period.start>period.end) throw new RangeError(`period.${name} must contain an ordered YYYY-MM-DD start/end range`);
  const requested=Array.isArray(input.kpis)?input.kpis:[];
  const unknown=requested.filter(k=>!DEFINITIONS[k]);
  if(unknown.length) throw new RangeError(`Unknown KPI(s): ${unknown.join(', ')}`);
  const quality=[];
  const affectedBySource={ga4:requested.filter(k=>DEFINITIONS[k][2]==='ga4'),meta:requested.filter(k=>DEFINITIONS[k][2]==='ads'),gads:requested.filter(k=>DEFINITIONS[k][2]==='ads')};
  for(const source of ['ga4','meta','gads']) if(input[source]==null&&affectedBySource[source].length) quality.push({code:'missing_source',source,affected_kpis:affectedBySource[source],detail:`${source} source was not provided; affected KPIs may be unavailable or partial.`});
  const results={};
  for(const [periodName,period] of Object.entries(input.period)){
    const ga4=input.ga4?sumRows(input.ga4.rows||[],GA4_KEYS,period,quality,'ga4'):empty(GA4_KEYS,null);
    const adsAvailable=input.meta!=null||input.gads!=null;
    if(adsAvailable){
      const meta=input.meta?sumRows(input.meta.rows||[],ADS_KEYS,period,quality,'meta'):empty(ADS_KEYS);
      const gads=input.gads?sumRows(input.gads.rows||[],ADS_KEYS,period,quality,'gads'):empty(ADS_KEYS);
      const combined=Object.fromEntries(ADS_KEYS.map(k=>[k,meta[k]+gads[k]]));
      results[periodName]={...ga4,...derived(combined,periodName,quality)};
    } else results[periodName]={...ga4,...empty([...ADS_KEYS,'ctr','cpc','cpl','roas'],null)};
  }
  const metrics=requested.map(key=>{
    const current=results.current[key],previous=results.previous[key];
    const delta=current==null||previous==null?null:current-previous;
    const pct=delta==null||previous===0?null:delta/Math.abs(previous);
    if(delta!=null&&previous===0) quality.push({code:'zero_previous',kpi:key,detail:`${key} percentage change is null because the previous value is zero.`});
    return {key,label:DEFINITIONS[key][0],unit:DEFINITIONS[key][1],current,previous,delta_abs:delta,delta_pct:pct,direction:delta==null||Math.abs(delta)<1e-12?'flat':delta>0?'up':'down'};
  });
  return {metrics,totals:{current:results.current,previous:results.previous},data_quality:quality,period_label:`${monthLabel(input.period.current.start)} vs ${monthLabel(input.period.previous.start)}`};
}
if(typeof module!=='undefined'&&module.exports) module.exports={buildKpiReport,KPI_DEFINITIONS:DEFINITIONS};
if(typeof $input!=='undefined'){
  const merged=$input.first().json;
  const input=merged.period?merged:{...$('Client Input').first().json,ga4:$('TODO: connect GA4').first().json,meta:$('TODO: connect Meta').first().json,gads:$('TODO: connect Google Ads').first().json,extra:$('TODO: connect Extra Source').first().json};
  input.kpis=Array.isArray(input.kpis)?input.kpis:String(input.kpis||'').split(',').map(k=>k.trim()).filter(Boolean);
  if(!input.period){
    const dateParts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:input.timezone||'UTC',year:'numeric',month:'2-digit'}).formatToParts(new Date()).map(({type,value})=>[type,value]));
    const year=Number(dateParts.year),month=Number(dateParts.month),iso=date=>date.toISOString().slice(0,10);
    input.period={current:{start:iso(new Date(Date.UTC(year,month-2,1))),end:iso(new Date(Date.UTC(year,month-1,0)))},previous:{start:iso(new Date(Date.UTC(year,month-3,1))),end:iso(new Date(Date.UTC(year,month-2,0)))}};
  }
  return [{json:buildKpiReport(input)}];
}

const report=$input.first().json;
const client=$('Prepare Client and Periods').first().json;
const row={timestamp:new Date().toISOString(),client_id:client.client_id,period_label:report.period_label};
for(const metric of report.metrics){row[`${metric.key}_current`]=metric.current;row[`${metric.key}_previous`]=metric.previous;row[`${metric.key}_delta_pct`]=metric.delta_pct;}
row.data_quality=JSON.stringify(report.data_quality);
return [{json:row}];

'use strict';

const DEFAULT_ACCENT = '#2563eb';

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function safeText(value, fallback) {
  const text = String(value ?? '').trim();
  return text || fallback;
}

function safeAccent(value) {
  const color = String(value ?? '').trim();
  return /^#[0-9a-f]{6}$/i.test(color) ? color : DEFAULT_ACCENT;
}

function safeLogo(value) {
  const url = String(value ?? '').trim();
  return /^https:\/\/[^\s]+$/i.test(url) ? url : null;
}

function finiteOrNull(value) {
  if (value === null || value === '' || value === undefined) return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function formatNumber(value) {
  const number = finiteOrNull(value);
  if (number === null) return 'n/a';
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(number);
}

function formatDelta(value) {
  const number = finiteOrNull(value);
  if (number === null) return 'n/a';
  return `${number > 0 ? '+' : ''}${(number * 100).toFixed(1)}%`;
}

function direction(value) {
  const number = finiteOrNull(value);
  if (number === null || Math.abs(number) < 1e-12) return { symbol: '–', color: '#64748b' };
  return number > 0
    ? { symbol: '▲', color: '#15803d' }
    : { symbol: '▼', color: '#b91c1c' };
}

function labelFor(key) {
  return key
    .split('_')
    .filter(Boolean)
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join(' ');
}

function metricRows(row) {
  const available = Object.keys(row)
    .filter((key) => key.endsWith('_current'))
    .map((currentKey) => currentKey.slice(0, -'_current'.length))
    .filter((key) => Object.hasOwn(row, `${key}_previous`));
  const paidMedia = ['spend', 'cpl', 'roas', 'ctr'].filter((key) =>
    available.includes(key) &&
    (finiteOrNull(row[`${key}_current`]) !== null || finiteOrNull(row[`${key}_previous`]) !== null));
  const keys = [
    ...available.filter((key) => !paidMedia.includes(key)).slice(0, 3),
    ...paidMedia,
  ];
  return keys
    .map((key) => ({
      key,
      label: labelFor(key),
      current: row[`${key}_current`],
      previous: row[`${key}_previous`],
      delta: row[`${key}_delta_pct`],
    }));
}

function dataNotes(value) {
  let notes = value;
  if (typeof notes === 'string') {
    try { notes = JSON.parse(notes); } catch { notes = [notes]; }
  }
  if (!Array.isArray(notes)) return [];
  return notes.map((note) => {
    if (typeof note === 'string') return note.trim();
    if (note && typeof note === 'object') {
      return safeText(note.detail, safeText(note.code, 'Data quality note'));
    }
    return '';
  }).filter(Boolean);
}

function whatChanged(metrics) {
  const comparable = metrics
    .map((metric) => ({ ...metric, numericDelta: finiteOrNull(metric.delta) }))
    .filter((metric) => metric.numericDelta !== null)
    .sort((left, right) => Math.abs(right.numericDelta) - Math.abs(left.numericDelta) || left.key.localeCompare(right.key));
  if (!comparable.length) return 'No comparable percentage change is available for the displayed KPIs.';
  const lead = comparable[0];
  const verb = lead.numericDelta > 0 ? 'increased' : lead.numericDelta < 0 ? 'decreased' : 'was flat';
  return `${lead.label} ${verb} by ${formatDelta(Math.abs(lead.numericDelta))} versus the previous period.`;
}

function renderReport(row, client = {}) {
  if (!row || typeof row !== 'object' || Array.isArray(row)) throw new TypeError('Report row must be an object.');
  const agency = safeText(client.agency, 'Agency');
  const reportName = safeText(client.report_name, 'Performance Report');
  const periodLabel = safeText(row.period_label, 'Current vs previous period');
  const accent = safeAccent(client.brand_color);
  const logo = safeLogo(client.logo_url);
  const metrics = metricRows(row);
  const notes = dataNotes(row.data_quality);
  const changed = whatChanged(metrics);
  const subject = `${agency} — ${reportName} — ${periodLabel}`;

  const tableRows = metrics.map((metric) => {
    const trend = direction(metric.delta);
    return `<tr><td style="padding:10px;border-bottom:1px solid #e2e8f0;font-weight:600">${escapeHtml(metric.label)}</td><td style="padding:10px;border-bottom:1px solid #e2e8f0;text-align:right">${escapeHtml(formatNumber(metric.current))}</td><td style="padding:10px;border-bottom:1px solid #e2e8f0;text-align:right">${escapeHtml(formatNumber(metric.previous))}</td><td style="padding:10px;border-bottom:1px solid #e2e8f0;text-align:right;color:${trend.color};font-weight:700">${trend.symbol} ${escapeHtml(formatDelta(metric.delta))}</td></tr>`;
  }).join('');
  const notesHtml = notes.length
    ? `<h2 style="font-size:16px;margin:24px 0 8px">Data notes</h2><ul style="margin:0;padding-left:20px">${notes.map((note) => `<li style="margin:6px 0">${escapeHtml(note)}</li>`).join('')}</ul>`
    : '';
  const logoHtml = logo ? `<img src="${escapeHtml(logo)}" alt="${escapeHtml(agency)} logo" style="display:block;max-height:48px;max-width:180px;margin-bottom:16px">` : '';
  const html = `<!doctype html><html><body style="margin:0;background:#f8fafc;color:#0f172a;font-family:Arial,sans-serif"><div style="max-width:720px;margin:0 auto;padding:24px"><div style="background:#ffffff;border-top:6px solid ${accent};padding:28px;border-radius:8px">${logoHtml}<h1 style="margin:0 0 6px;font-size:24px">${escapeHtml(reportName)}</h1><p style="margin:0 0 24px;color:#475569">${escapeHtml(agency)} · ${escapeHtml(periodLabel)}</p><table role="presentation" style="width:100%;border-collapse:collapse"><thead><tr style="background:${accent};color:#ffffff"><th style="padding:10px;text-align:left">KPI</th><th style="padding:10px;text-align:right">Current</th><th style="padding:10px;text-align:right">Previous</th><th style="padding:10px;text-align:right">Δ</th></tr></thead><tbody>${tableRows}</tbody></table><h2 style="font-size:16px;margin:24px 0 8px">What changed</h2><p style="margin:0">${escapeHtml(changed)}</p>${notesHtml}</div></div></body></html>`;

  const textMetrics = metrics.map((metric) => {
    const trend = direction(metric.delta);
    return `${metric.label}: ${formatNumber(metric.current)} current | ${formatNumber(metric.previous)} previous | ${trend.symbol} ${formatDelta(metric.delta)}`;
  });
  const text = [
    subject,
    '',
    ...textMetrics,
    '',
    `What changed: ${changed}`,
    ...(notes.length ? ['', 'Data notes:', ...notes.map((note) => `- ${note}`)] : []),
  ].join('\n');

  return { subject, html, text };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { renderReport };
if (typeof $input !== 'undefined') {
  const row = $('Build Reports Row').first().json;
  const client = $('Prepare Client and Periods').first().json;
  return [{ json: { ...row, ...renderReport(row, client), report_pdf: null } }];
}

'use strict';

const TELEGRAM_LIMIT = 4096;

function recipients(value) {
  const entries = Array.isArray(value) ? value : String(value ?? '').split(',');
  return [...new Set(entries.map((entry) => String(entry).trim()).filter(Boolean))];
}

function telegramText(value) {
  const text = String(value ?? '');
  if (text.length <= TELEGRAM_LIMIT) return text;
  return `${text.slice(0, TELEGRAM_LIMIT - 1)}…`;
}

function buildDelivery(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    throw new TypeError('Delivery item must be an object.');
  }
  const to = recipients(item.recipients);
  const rawChatId = String(item.telegram_chat_id ?? '').trim();
  const chatId = rawChatId && rawChatId !== '0' ? rawChatId : '';
  return {
    gmail: {
      send: to.length > 0,
      to,
      subject: String(item.subject ?? ''),
      html: String(item.html ?? ''),
    },
    telegram: {
      send: Boolean(chatId),
      chatId,
      text: telegramText(item.text),
    },
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { buildDelivery, TELEGRAM_LIMIT };
}
if (typeof $input !== 'undefined') {
  const rendered = $input.first().json;
  const client = $('Prepare Client and Periods').first().json;
  const item = {
    ...rendered,
    recipients: rendered.recipients ?? client.recipients,
    telegram_chat_id: rendered.telegram_chat_id ?? client.telegram_chat_id,
    client_id: rendered.client_id ?? client.client_id,
  };
  return [{ json: { ...item, ...buildDelivery(item) } }];
}

'use strict';

const PURCHASE_TYPES = new Set([
  'offsite_conversion.fc_purchase',
  'offsite_conversion.fb_pixel_purchase',
  'purchase',
]);

function numeric(value, field, rowIndex) {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    throw new TypeError(`Meta insight ${rowIndex + 1} has a non-numeric ${field} value.`);
  }
  return number;
}

function dateValue(value, rowIndex) {
  const date = String(value ?? '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(Date.parse(`${date}T00:00:00Z`))) {
    throw new TypeError(`Meta insight ${rowIndex + 1} has an invalid date_start.`);
  }
  return date;
}

function actionTotal(entries, predicate, field, rowIndex) {
  if (entries == null) return 0;
  if (!Array.isArray(entries)) throw new TypeError(`Meta insight ${rowIndex + 1} ${field} must be an array.`);
  return entries
    .filter((entry) => predicate(String(entry?.action_type ?? '')))
    .reduce((sum, entry) => sum + numeric(entry.value, `${field}.${entry.action_type}`, rowIndex), 0);
}

function mapMetaInsights(response) {
  if (!response || typeof response !== 'object' || Array.isArray(response)) {
    throw new TypeError('Meta insights response must be an object.');
  }
  if (!Array.isArray(response.data)) throw new TypeError('Meta insights response.data must be an array.');
  const rows = response.data.map((insight, rowIndex) => ({
    date: dateValue(insight.date_start, rowIndex),
    spend: numeric(insight.spend, 'spend', rowIndex),
    impressions: numeric(insight.impressions, 'impressions', rowIndex),
    clicks: numeric(insight.clicks, 'clicks', rowIndex),
    ctr: numeric(insight.ctr, 'ctr', rowIndex),
    cpc: numeric(insight.cpc, 'cpc', rowIndex),
    leads: actionTotal(insight.actions, (type) => type === 'lead', 'actions', rowIndex),
    purchases: actionTotal(insight.actions, (type) => PURCHASE_TYPES.has(type), 'actions', rowIndex),
    revenue: actionTotal(insight.action_values, (type) => PURCHASE_TYPES.has(type), 'action_values', rowIndex),
  }));
  rows.sort((left, right) => left.date.localeCompare(right.date));
  return { rows };
}

if (typeof module !== 'undefined' && module.exports) module.exports = { mapMetaInsights };
if (typeof $input !== 'undefined') {
  return [{ json: { meta: mapMetaInsights($input.first().json) } }];
}

const client=$('Prepare Client and Periods').first().json;
const sources=$input.first().json;
return [{json:{...client,ga4:sources.ga4,meta:sources.meta??null,gads:null,extra:null}}];
